mapper.select:
WITH samples AS ( SELECT sample_unique_id, sample_stable_id, patient_stable_id FROM sample_derived WHERE cancer_study_identifier = #{studyId}
AND sample_unique_id IN (#{sampleUniqueIds, typeHandler=org.apache.ibatis.type.ArrayTypeHandler})
) SELECT #{molecularProfileId} AS "molecularProfileId", s.sample_stable_id AS "sampleId", s.patient_stable_id AS "patientId", #{studyId} AS "studyId", d.entity_stable_id AS "genericAssayStableId",
, d.patient_level != 0 AS "patientLevel" FROM generic_assay_data_derived d INNER JOIN samples s ON s.sample_unique_id = d.sample_unique_id WHERE d.profile_type = #{profileType} AND d.profile_stable_id = #{molecularProfileId} AND d.value != '' AND d.value != 'NA'
AND d.entity_stable_id IN #{item}
AND d.sample_unique_id IN (SELECT sample_unique_id FROM samples)
